/* eslint-disable max-len, max-params */

'use strict';

// FUNCTIONS //

/**
* Solve AT * X = B using the LU factorization of A computed by `dgttrf`, overwriting B with the solution.
*
* @private
* @param {NonNegativeInteger} N - order of the matrix A
* @param {NonNegativeInteger} nrhs - number of right-hand sides, i.e., the number of columns of the matrix B
* @param {Float64Array} DL - multipliers that define the matrix L
* @param {integer} strideDL - stride length for DL
* @param {NonNegativeInteger} offsetDL - starting index of DL
* @param {Float64Array} D - N diagonal elements of the upper triangular matrix U
* @param {integer} strideD - stride length for D
* @param {NonNegativeInteger} offsetD - starting index of D
* @param {Float64Array} DU - elements of the first super-diagonal of U
* @param {integer} strideDU - stride length for DU
* @param {NonNegativeInteger} offsetDU - starting index of DU
* @param {Float64Array} DU2 - elements of the second super-diagonal of U
* @param {integer} strideDU2 - stride length for DU2
* @param {NonNegativeInteger} offsetDU2 - starting index of DU2
* @param {Int32Array} IPIV - vector of pivot indices
* @param {integer} strideIPIV - stride length for IPIV
* @param {NonNegativeInteger} offsetIPIV - starting index for IPIV
* @param {Float64Array} B - right-hand side matrix B, overwritten by the solution matrix X
* @param {integer} strideB1 - stride of the first dimension of B
* @param {integer} strideB2 - stride of the second dimension of B
* @param {NonNegativeInteger} offsetB - starting index of B
* @returns {Float64Array} the solution matrix X
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Int32Array = require( '@stdlib/array/int32' );
*
* var DL = new Float64Array( [ 0.25, 0.26666667 ] );
* var D = new Float64Array( [ 4.0, 3.75, 3.73333333 ] );
* var DU = new Float64Array( [ 1.0, 0.73333333 ] );
* var DU2 = new Float64Array( [ 0.0 ] );
* var IPIV = new Int32Array( [ 0, 1, 2 ] );
* var B = new Float64Array( [ 7.0, 8.0, 7.0 ] );
*
* var out = transpose( 3, 1, DL, 1, 0, D, 1, 0, DU, 1, 0, DU2, 1, 0, IPIV, 1, 0, B, 1, 1, 0 );
* // out => <Float64Array>[ ~1.44, ~1.25, ~1.55 ]
*/
function transpose( N, nrhs, DL, strideDL, offsetDL, D, strideD, offsetD, DU, strideDU, offsetDU, DU2, strideDU2, offsetDU2, IPIV, strideIPIV, offsetIPIV, B, strideB1, strideB2, offsetB ) {
	var idu2;
	var temp;
	var ipi;
	var idu;
	var idl;
	var id;
	var ib;
	var ip;
	var i;
	var j;

	ip = offsetIPIV + ( (N-2) * strideIPIV );
	ib = offsetB;
	idl = offsetDL + ( (N-2) * strideDL );
	id = offsetD;
	idu = offsetDU;
	idu2 = offsetDU2;

	if ( nrhs <= 1 ) {
		for ( j = 0; j < nrhs; j++) {
			B[ offsetB + (strideB2*j) ] = B[ offsetB + (strideB2*j) ] / D[ id ];
			if ( N > 1 ) {
				B[ offsetB + strideB1 + (strideB2*j) ] = ( B[ offsetB + strideB1 + (strideB2*j) ] - ( DU[ idu ] * B[ offsetB + (strideB2*j) ] ) ) / D[ id + strideD ];
			}

			idu = offsetDU + strideDU;
			id = offsetD + ( 2 * strideD );
			for ( i = 2; i < N; i++ ) {
				B[ offsetB + (strideB1*i) + (strideB2*j) ] = ( B[ offsetB + (strideB1*i) + (strideB2*j) ] - ( DU[ idu ] * B[ offsetB + (strideB1*(i-1)) + (strideB2*j) ] ) - ( DU2[ idu2 ] * B[ offsetB + (strideB1*(i-2)) + (strideB2*j) ] ) ) / D[ id ];

				idu += strideDU;
				idu2 += strideDU2;
				id += strideD;
			}
			for ( i = N - 2; i >= 0; i-- ) {
				ipi = IPIV[ ip ];
				temp = B[ offsetB + (strideB1*i) + (strideB2*j) ] - ( DL[ idl ] * B[ offsetB + (strideB1*(i+1)) + (strideB2*j) ] );
				B[ offsetB + (strideB1*i) + (strideB2*j) ] = B[ offsetB + (strideB1*ipi) + (strideB2*j) ];
				B[ offsetB + (strideB1*ipi) + (strideB2*j) ] = temp;

				ip -= strideIPIV;
				idl -= strideDL;
			}
		}
	} else {
		for ( j = 0; j < nrhs; j++ ) {
			B[ offsetB + (strideB2*j) ] /= D[ id ];
			if ( N > 1 ) {
				B[ offsetB + strideB1 + (strideB2*j) ] = ( B[ offsetB + strideB1 + (strideB2*j) ] - ( DU[ idu ] * B[ offsetB + (strideB2*j) ] ) ) / D[ id + strideD ];
			}
			for ( i = 2; i < N; i++ ) {
				B[ offsetB + (strideB1*i) + (strideB2*j) ] = ( B[ offsetB + (strideB1*i) + (strideB2*j) ] - ( DU[ offsetDU + (strideDU*(i-1)) ] * B[ offsetB + (strideB1*(i-1)) + (strideB2*j) ] ) - ( DU2[ offsetDU2 + (strideDU2*(i-2)) ] * B[ offsetB + (strideB1*(i-2)) + (strideB2*j) ] ) ) / D[ offsetD + (strideD*i) ];
			}
			for ( i = N - 2; i >= 0; i-- ) {
				if ( IPIV[ offsetIPIV + (i * strideIPIV) ] === i ) {
					B[ offsetB + (strideB1*i) + (strideB2*j) ] -= DL[ offsetDL + (strideDL*i) ] * B[ offsetB + (strideB1*(i+1)) + (strideB2*j) ];
				} else {
					temp = B[ offsetB + (strideB1*(i+1)) + (strideB2*j) ];
					B[ offsetB + (strideB1*(i+1)) + (strideB2*j) ] = B[ offsetB + (strideB1*i) + (strideB2*j) ] - ( DL[ offsetDL + (strideDL*i) ] * temp );
					B[ offsetB + (strideB1*i) + (strideB2*j) ] = temp;
				}
			}
		}
	}

	return B;
}

/**
* Solve A * X = B using the LU factorization of A computed by `dgttrf`, overwriting B with the solution.
*
* @private
* @param {NonNegativeInteger} N - order of the matrix A
* @param {NonNegativeInteger} nrhs - number of right-hand sides, i.e., the number of columns of the matrix B
* @param {Float64Array} DL - multipliers that define the matrix L
* @param {integer} strideDL - stride length for DL
* @param {NonNegativeInteger} offsetDL - starting index of DL
* @param {Float64Array} D - N diagonal elements of the upper triangular matrix U
* @param {integer} strideD - stride length for D
* @param {NonNegativeInteger} offsetD - starting index of D
* @param {Float64Array} DU - elements of the first super-diagonal of U
* @param {integer} strideDU - stride length for DU
* @param {NonNegativeInteger} offsetDU - starting index of DU
* @param {Float64Array} DU2 - elements of the second super-diagonal of U
* @param {integer} strideDU2 - stride length for DU2
* @param {NonNegativeInteger} offsetDU2 - starting index of DU2
* @param {Int32Array} IPIV - vector of pivot indices
* @param {integer} strideIPIV - stride length for IPIV
* @param {NonNegativeInteger} offsetIPIV - starting index for IPIV
* @param {Float64Array} B - right-hand side matrix B, overwritten by the solution matrix X
* @param {integer} strideB1 - stride of the first dimension of B
* @param {integer} strideB2 - stride of the second dimension of B
* @param {NonNegativeInteger} offsetB - starting index of B
* @returns {Float64Array} the solution matrix X
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Int32Array = require( '@stdlib/array/int32' );
*
* var DL = new Float64Array( [ 0.25, 0.26666667 ] );
* var D = new Float64Array( [ 4.0, 3.75, 3.73333333 ] );
* var DU = new Float64Array( [ 1.0, 0.73333333 ] );
* var DU2 = new Float64Array( [ 0.0 ] );
* var IPIV = new Int32Array( [ 0, 1, 2 ] );
* var B = new Float64Array( [ 7.0, 8.0, 7.0 ] );
*
* var out = noTranspose( 3, 1, DL, 1, 0, D, 1, 0, DU, 1, 0, DU2, 1, 0, IPIV, 1, 0, B, 1, 1, 0 );
* // out => <Float64Array>[ ~1.40, ~1.39, ~1.43 ]
*/
function noTranspose( N, nrhs, DL, strideDL, offsetDL, D, strideD, offsetD, DU, strideDU, offsetDU, DU2, strideDU2, offsetDU2, IPIV, strideIPIV, offsetIPIV, B, strideB1, strideB2, offsetB ) {
	var temp;
	var idu2;
	var ipi;
	var idl;
	var idu;
	var ip;
	var ib;
	var id;
	var j;
	var i;

	ip = offsetIPIV;
	ib = offsetB;
	idl = offsetDL;
	id = offsetD;
	idu = offsetDU;
	idu2 = offsetDU2;

	if ( nrhs <= 1 ) {
		for ( j = 0; j < nrhs; j++ ) {
			for ( i = 0; i < N - 1; i++ ) {
				ipi = IPIV[ offsetIPIV+(strideIPIV*i) ];
				temp = B[ offsetB + (strideB1*(i+1-ipi+i)) + (strideB2*j) ] - ( DL[ offsetDL + (i*strideDL) ] * B[ offsetB + (strideB1*ipi) + (strideB2*j) ] );
				B[ offsetB + (strideB1*i) + (strideB2*j) ] = B[ offsetB + (strideB1*ipi) + (strideB2*j) ];
				B[ offsetB + (strideB1*(i+1)) + (strideB2*j) ] = temp;
			}

			B[ offsetB + (strideB1*(N-1)) + (strideB2*j) ] /= D[ offsetD + (strideD*(N-1)) ];

			if ( N > 1 ) {
				B[ offsetB + (strideB1*(N-2)) + (strideB2*j) ] = ( B[ offsetB + (strideB1*(N-2)) + (strideB2*j) ] - ( DU[ offsetDU + (strideDU*(N-2)) ] * B[ offsetB + (strideB1*(N-1)) + (strideB2*j) ] ) ) / D[ offsetD + (strideD*(N-2)) ];
			}
			for ( i = N - 3; i >= 0; i-- ) {
				B[ offsetB + (strideB1*i) + (strideB2*j) ] = ( B[ offsetB + (strideB1*i) + (strideB2*j) ] - ( DU[ offsetDU + (strideDU*i) ] * B[ offsetB + (strideB1*(i+1)) + (strideB2*j) ] ) - ( DU2[ offsetDU2 + (strideDU2*i) ] * B[ offsetB + (strideB1*(i+2)) + (strideB2*j) ] ) ) / D[ offsetD + (strideD*i) ];
			}
		}
	} else {
		for ( j = 0; j < nrhs; j++ ) {
			for ( i = 0; i < N - 1; i++ ) {
				if ( IPIV[ offsetIPIV + (strideIPIV*i) ] === i ) {
					B[ offsetB + (strideB1*(i+1)) + (strideB2*j) ] -= DL[ offsetDL + (i*strideDL) ] * B[ offsetB + (strideB1*i) + (strideB2*j) ];
				} else {
					temp = B[ offsetB + (strideB1*i) + (strideB2*j) ];
					B[ offsetB + (strideB1*i) + (strideB2*j) ] = B[ offsetB + (strideB1*(i+1)) + (strideB2*j) ];
					B[ offsetB + (strideB1*(i+1)) + (strideB2*j) ] = temp - ( DL[ offsetDL + (i*strideDL) ] * B[ offsetB + (strideB1*i) + (strideB2*j) ] );
				}
			}
			B[ offsetB + (strideB1*(N-1)) + (strideB2*j) ] /= D[ offsetD + (strideD*(N-1)) ];

			if ( N > 1 ) {
				B[ offsetB + (strideB1*(N-2)) + (strideB2 * j) ] = ( B[ offsetB + (strideB1*(N-2)) + (strideB2*j) ] - ( DU[ offsetDU + (strideDU*(N-2)) ] * B[ offsetB + (strideB1*(N-1)) + (strideB2*j) ] ) ) / D[ offsetD + (strideD*(N-2)) ];
			}
			for ( i = N - 3; i >= 0; i-- ) {
				B[ offsetB + (strideB1*i) + (strideB2*j) ] = ( B[ offsetB + (strideB1*i) + (strideB2*j) ] - ( DU[ offsetDU + (strideDU*i) ] * B[ offsetB + (strideB1*(i+1)) + (strideB2*j) ] ) - ( DU2[ offsetDU2 + (strideDU2*i) ] * B[ offsetB + (strideB1*(i+2)) + (strideB2*j) ] ) ) / D[ offsetD + (strideD*i) ];
			}
		}
	}

	return B;
}


// MAIN //

/**
* Solves a system of linear equations with a tri diagonal matrix using the LU factorization computed by `dgttrf`.
*
* ## Notes
*
* -   To solve A * X = B (no transpose), use itrans = 0.
* -   To solve AT * X = B (transpose), use itrans = 1.
* -   To solve AT * X = B (conjugate transpose = transpose), use itrans = 2.
*
* @param {integer} itrans - specifies the form of the system of equations
* @param {NonNegativeInteger} N - order of the matrix A
* @param {NonNegativeInteger} nrhs - number of right-hand sides, i.e., the number of columns of the matrix B
* @param {Float64Array} DL - multipliers that define the matrix L
* @param {integer} strideDL - stride length for DL
* @param {NonNegativeInteger} offsetDL - starting index of DL
* @param {Float64Array} D - N diagonal elements of the upper triangular matrix U
* @param {integer} strideD - stride length for D
* @param {NonNegativeInteger} offsetD - starting index of D
* @param {Float64Array} DU - elements of the first super-diagonal of U
* @param {integer} strideDU - stride length for DU
* @param {NonNegativeInteger} offsetDU - starting index of DU
* @param {Float64Array} DU2 - elements of the second super-diagonal of U
* @param {integer} strideDU2 - stride length for DU2
* @param {NonNegativeInteger} offsetDU2 - starting index of DU2
* @param {Int32Array} IPIV - vector of pivot indices
* @param {integer} strideIPIV - stride length for IPIV
* @param {NonNegativeInteger} offsetIPIV - starting index for IPIV
* @param {Float64Array} B - right-hand side matrix B, overwritten by the solution matrix X
* @param {integer} strideB1 - stride of the first dimension of B
* @param {integer} strideB2 - stride of the second dimension of B
* @param {NonNegativeInteger} offsetB - starting index of B
* @returns {Float64Array} the solution matrix X
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Int32Array = require( '@stdlib/array/int32' );
*
* var DL = new Float64Array( [ 0.25, 0.26666667 ] );
* var D = new Float64Array( [ 4.0, 3.75, 3.73333333 ] );
* var DU = new Float64Array( [ 1.0, 0.73333333 ] );
* var DU2 = new Float64Array( [ 0.0 ] );
* var IPIV = new Int32Array( [ 0, 1, 2 ] );
* var B = new Float64Array( [ 7.0, 8.0, 7.0 ] );
*
* var out = dgtts2( 1, 3, 1, DL, 1, 0, D, 1, 0, DU, 1, 0, DU2, 1, 0, IPIV, 1, 0, B, 1, 1, 0 );
* // out => <Float64Array>[ ~1.44, ~1.25, ~1.55 ]
*/
function dgtts2( itrans, N, nrhs, DL, strideDL, offsetDL, D, strideD, offsetD, DU, strideDU, offsetDU, DU2, strideDU2, offsetDU2, IPIV, strideIPIV, offsetIPIV, B, strideB1, strideB2, offsetB ) {
	if ( N === 0 || nrhs === 0 ) {
		return B;
	}
	if ( itrans === 0 ) {
		// Solve A * X = B using the LU factorization of A, overwriting B with the solution
		return noTranspose( N, nrhs, DL, strideDL, offsetDL, D, strideD, offsetD, DU, strideDU, offsetDU, DU2, strideDU2, offsetDU2, IPIV, strideIPIV, offsetIPIV, B, strideB1, strideB2, offsetB );
	}
	// Solve Solve A**T * X = B using the LU factorization of A,  overwriting B with the solution.
	return transpose( N, nrhs, DL, strideDL, offsetDL, D, strideD, offsetD, DU, strideDU, offsetDU, DU2, strideDU2, offsetDU2, IPIV, strideIPIV, offsetIPIV, B, strideB1, strideB2, offsetB );
}


// EXPORTS //

module.exports = dgtts2;
